public class GridTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("coordinate grid 2x3", "0,0 0,1 0,2\n1,0 1,1 1,2",
                Grid.render(2, 3, (r, c) -> r + "," + c));
        check("constant cells 2x2", "* *\n* *",
                Grid.render(2, 2, (r, c) -> "*"));
        check("checkerboard 3x3", "X O X\nO X O\nX O X",
                Grid.render(3, 3, (r, c) -> (r + c) % 2 == 0 ? "X" : "O"));
        check("single cell", "7", Grid.render(1, 1, (r, c) -> "7"));
        check("one row uses no newline", "a a a a", Grid.render(1, 4, (r, c) -> "a"));
        check("one column has no spaces", "0\n1\n2", Grid.render(3, 1, (r, c) -> String.valueOf(r)));
        check("zero rows gives empty string", "", Grid.render(0, 5, (r, c) -> "x"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

