public class Grid {

    public static String render(int rows, int cols, java.util.function.BiFunction<Integer, Integer, String> cell) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            if (r > 0) {
                sb.append("\n");
            }
            for (int c = 0; c < cols; c++) {
                if (c > 0) {
                    sb.append(" ");
                }
                sb.append(cell.apply(r, c));
            }
        }
        return sb.toString();
    }
}
